package main
import("encoding/json";"net/http";"strings";"time")
type breakerInput struct{ID string `json:"id"`;Name string `json:"name"`;Description string `json:"description"`;FailureThreshold int `json:"failureThreshold"`;RollingWindowSize int `json:"rollingWindowSize"`;OpenCooldownSteps int `json:"openCooldownSteps"`;HalfOpenMaxProbes int `json:"halfOpenMaxProbes"`;HalfOpenSuccessThreshold int `json:"halfOpenSuccessThreshold"`;Reset bool `json:"reset"`}
func Handler(w http.ResponseWriter,r *http.Request){if r.Method==http.MethodOptions{w.WriteHeader(204);return};switch r.Method{case http.MethodGet:app.mu.Lock();out:=make([]Breaker,0,len(app.breakers));for _,b:=range app.breakers{out=append(out,clone(b))};app.mu.Unlock();jsonOut(w,200,map[string]any{"breakers":out,"engine":"active"});case http.MethodPost:var in breakerInput;if e:=json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20)).Decode(&in);e!=nil{errOut(w,400,"invalid JSON");return};in.ID=strings.TrimSpace(in.ID);if in.ID==""{errOut(w,400,"id is required");return};app.mu.Lock();b:=app.breakers[in.ID];if b==nil{if strings.TrimSpace(in.Name)==""{app.mu.Unlock();errOut(w,400,"name is required");return};b=&Breaker{ID:in.ID,Name:in.Name,State:"CLOSED",FailureThreshold:5,RollingWindowSize:10,OpenCooldownSteps:4,HalfOpenMaxProbes:3,HalfOpenSuccessThreshold:2};app.breakers[in.ID]=b};if in.Name!=""{b.Name=in.Name};if in.Description!=""{b.Description=in.Description};if in.FailureThreshold>0{b.FailureThreshold=clamp(in.FailureThreshold,1,1000)};if in.RollingWindowSize>0{b.RollingWindowSize=clamp(in.RollingWindowSize,1,1000)};if in.OpenCooldownSteps>0{b.OpenCooldownSteps=clamp(in.OpenCooldownSteps,1,1000)};if in.HalfOpenMaxProbes>0{b.HalfOpenMaxProbes=clamp(in.HalfOpenMaxProbes,1,100)};if in.HalfOpenSuccessThreshold>0{b.HalfOpenSuccessThreshold=clamp(in.HalfOpenSuccessThreshold,1,b.HalfOpenMaxProbes)};if in.Reset{b.State="CLOSED";b.ConsecutiveFailures=0;b.OpenStepsRemaining=0;b.HalfOpenSuccesses=0;b.HalfOpenAttempts=0;b.window=nil};b.UpdatedAt=time.Now().UTC();out:=clone(b);app.mu.Unlock();jsonOut(w,200,map[string]any{"breaker":out});default:w.Header().Set("Allow","GET, POST, OPTIONS");errOut(w,405,"method not allowed")}}
